def ages(date):
    date=np.asarray(date);table={}
    try:
        for x in np.unique(date):table[x]=datetime.datetime.strptime(str(iv(x)).zfill(8),"%Y%m%d").date().toordinal()
    except ValueError:table={x:i for i,x in enumerate(sorted(np.unique(date).tolist()))}
    q=np.asarray([table[x] for x in date],dtype=np.float64);return q.max()-q


