def predict(model,X,device):
    model.eval();o=[]
    with torch.no_grad():
        for i in range(0,len(X),32768):o.append(model(X[i:i+32768].to(device)).cpu().numpy())
    return np.nan_to_num(np.concatenate(o).astype(np.float64),nan=0.0,posinf=30.0,neginf=-30.0)


